void QuickTimeVideo::multipleEntriesDecoder() {
  DataBuf buf(4 + 1);
  io_->read(buf.data(), 4);
  io_->read(buf.data(), 4);
  size_t noOfEntries;

  noOfEntries = returnUnsignedBufValue(buf);

  for (unsigned long i = 1; i <= noOfEntries; i++)
    decodeBlock();
}  // QuickTimeVideo::multipleEntriesDecoder
